import{attachAdditionalGameplay}from'./attach-additional-gameplay.mjs';
import{S4HubScene}from'../gohyeon-pair/hub-scene.mjs';
import{AutoS4EncounterTargetScene,AutoS4DistanceHubScene}from'./encounter/movement-proof.mjs';
import{prepareS4PrologueProvider}from'./recovery/prologue-provider.mjs';
import{createS4TargetRenderer}from'./render-gameplay-target.mjs';
import{attachSelectedGameplay}from'./decorate-target-scene.mjs';
const gameplayHint=scene=>{const original=scene.proximityHint?.bind(scene),hint=()=>original?.()||(scene.mapId==='world:hub:PROLOGUE'?'원래 회복 지점 · 지역 출구는 아직 연결되지 않았습니다.':scene.mapId==='world:hub:S4'?'고현 · 센터·마트·두 지역 연결 개발 검토 · 사용자 저장 없음':'선정 트레이너·역사·관찰·서식지 연결 개발 검토 · 사용자 저장 없음');if(Object.isFrozen(scene))return Object.freeze({...scene,proximityHint:hint});scene.proximityHint=hint;return scene};
// Fixed S4 selected three scenes only; reuse the original hub services/house/environment path.
export function createSelectedGameplayScenePreparer({hubInputs,targetInputs,registry,scratchFactory,playerActors,foregroundLayers,npcs,geometry,encounterGeometry,getWorld,fetcher,decode,signal}){if(!playerActors||typeof getWorld!=='function')throw Error('CURRENT_GAMEPLAY_INPUTS_REQUIRED');const inputs={...hubInputs,masks:{...hubInputs.masks,...targetInputs.hubMasks}},renderer=createS4TargetRenderer({inputs:targetInputs,actors:playerActors,scratchFactory,foregroundLayers,npcs});let epoch=0;return async location=>{if(registry.validate(location))throw Error('UNREGISTERED_TARGET_LOCATION');const sessionEpoch=++epoch;if(location.mapId==='world:hub:PROLOGUE')return gameplayHint(await prepareS4PrologueProvider({location,registry,sessionEpoch,signal,fetcher,decode,canvasFactory:scratchFactory}));if(location.mapId==='world:hub:S4')return gameplayHint(attachAdditionalGameplay(new AutoS4DistanceHubScene({location,registry,inputs,scratchFactory,sessionEpoch}),{getWorld}));if(!['world:area:S4_POW_CAMP_PARK_EDGE','world:area:S4_GOHYEON_GREENBELT'].includes(location.mapId))throw Error('UNKNOWN_FIXED_S4_SCENE');const scene=new AutoS4EncounterTargetScene({encounterGeometry,location,registry,safeMask:location.mapId.endsWith('PARK_EDGE')?targetInputs.park.mask:targetInputs.green.mask,renderer,sessionEpoch});try{return gameplayHint(attachAdditionalGameplay(attachSelectedGameplay(scene,{geometry,getWorld}),{getWorld}))}catch(e){scene.dispose();throw e}}}
